<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceBankService{
 public static function bankReconciliations(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::BANK_RECONCILE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT r.*,a.code account_code,a.name account_name,(SELECT COUNT(*) FROM ".Db::table('bank_statement_lines')." l WHERE l.reconciliation_id=r.id AND l.status='unmatched') unmatched_lines FROM ".Db::table('bank_reconciliations')." r JOIN ".Db::table('accounts')." a ON a.id=r.bank_account_id WHERE r.company_id=%d AND r.branch_id=%d ORDER BY r.id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function bankDetail(Actor $a,int $id):array{$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,a.code account_code,a.name account_name FROM ".Db::table('bank_reconciliations')." r JOIN ".Db::table('accounts')." a ON a.id=r.bank_account_id WHERE r.id=%d AND r.company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Bank reconciliation not found.','bank_reconciliation_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('bank_statement_lines')." WHERE reconciliation_id=%d ORDER BY txn_date,id",$id),ARRAY_A);$candidates=(array)$db->get_results($db->prepare("SELECT jl.id journal_line_id,je.entry_no,je.entry_date,je.source_type,je.source_id,jl.debit,jl.credit,jl.description FROM ".Db::table('journal_lines')." jl JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id WHERE je.company_id=%d AND je.status='posted' AND je.branch_id=%d AND jl.account_id=%d AND DATE(je.entry_date) BETWEEN %s AND %s AND NOT EXISTS(SELECT 1 FROM ".Db::table('bank_statement_lines')." x WHERE x.matched_journal_line_id=jl.id AND x.status='matched') ORDER BY je.entry_date,je.id,jl.id",$a->companyId,(int)$r['branch_id'],(int)$r['bank_account_id'],$r['statement_from'],$r['statement_to']),ARRAY_A);return['reconciliation'=>$r,'lines'=>$lines,'journal_candidates'=>$candidates];}
 public static function bankCreate(Actor $a,int $branch,int $account,string $from,string $to,float $opening,float $closing):array{[$from,$to]=Input::dateRange($from,$to,'Bank statement period');$opening=round($opening,2);$closing=round($closing,2);Guard::branch($a,$branch,Capabilities::BANK_RECONCILE);AccountingService::bankAccount($a,$account);return Transaction::run(function()use($a,$branch,$account,$from,$to,$opening,$closing){$db=Db::wpdb();$accountTable=Db::table('accounts');$locked=$db->get_var($db->prepare("SELECT id FROM {$accountTable} WHERE id=%d AND company_id=%d AND active=1 FOR UPDATE",$account,$a->companyId));if(!$locked)throw new DomainException('Bank account not found.','bank_account_invalid',422);$overlap=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('bank_reconciliations')." WHERE company_id=%d AND bank_account_id=%d AND status IN ('draft','finalized') AND NOT(statement_to<%s OR statement_from>%s)",$a->companyId,$account,$from,$to));if($overlap)throw new DomainException('Overlapping bank reconciliation already exists for this account.','bank_reconciliation_overlap',409);Db::mustInsert($db,Db::table('bank_reconciliations'),['company_id'=>$a->companyId,'branch_id'=>$branch,'bank_account_id'=>$account,'statement_from'=>$from,'statement_to'=>$to,'opening_balance'=>$opening,'closing_balance'=>$closing,'status'=>'draft','created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'bank_reconciliation.create','bank_reconciliation',$id,['branch_id'=>$branch,'account_id'=>$account]);return['id'=>$id,'status'=>'draft'];});}
 public static function bankImport(Actor $a,int $id,array $lines):array{Guard::cap($a,Capabilities::BANK_RECONCILE);if(!$lines)throw new DomainException('Statement lines are required.');return Transaction::run(function()use($a,$id,$lines){$db=Db::wpdb();$h=Db::table('bank_reconciliations');$r=$db->get_row($db->prepare("SELECT * FROM {$h} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='draft')throw new DomainException('Draft reconciliation not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);$count=0;foreach($lines as$x){$dr=round((float)($x['debit']??0),2);$cr=round((float)($x['credit']??0),2);$date=Input::date((string)($x['txn_date']??''),'Bank transaction date');if($date<(string)$r['statement_from']||$date>(string)$r['statement_to'])throw new DomainException('Bank transaction date is outside the reconciliation period.','bank_line_date_outside_period',422);if(($dr>0)==($cr>0))throw new DomainException('Each statement line needs either debit or credit.');Db::mustInsert($db,Db::table('bank_statement_lines'),['reconciliation_id'=>$id,'txn_date'=>$date,'description'=>(string)($x['description']??''),'reference'=>(string)($x['reference']??''),'debit'=>$dr,'credit'=>$cr,'status'=>'unmatched']);$count++;}Audit::add($a,'bank_reconciliation.import','bank_reconciliation',$id,['branch_id'=>(int)$r['branch_id'],'imported'=>$count]);return['id'=>$id,'imported'=>$count];});}
 public static function bankMatch(Actor $a,int $line,int $journalLine):array{
  Guard::cap($a,Capabilities::BANK_RECONCILE);
  return Transaction::run(function()use($a,$line,$journalLine){
   $db=Db::wpdb();$l=$db->get_row($db->prepare("SELECT bl.*,r.company_id,r.branch_id,r.bank_account_id,r.statement_from,r.statement_to,r.status recon_status FROM ".Db::table('bank_statement_lines')." bl JOIN ".Db::table('bank_reconciliations')." r ON r.id=bl.reconciliation_id WHERE bl.id=%d AND r.company_id=%d FOR UPDATE",$line,$a->companyId),ARRAY_A);if(!$l||$l['recon_status']!=='draft'||$l['status']!=='unmatched')throw new DomainException('Unmatched bank line not found.');Guard::branch($a,(int)$l['branch_id'],Capabilities::BANK_RECONCILE);
   $j=$db->get_row($db->prepare("SELECT jl.*,je.status je_status,je.company_id,je.branch_id,je.entry_date FROM ".Db::table('journal_lines')." jl JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id WHERE jl.id=%d FOR UPDATE",$journalLine),ARRAY_A);if(!$j||(int)$j['company_id']!==$a->companyId||(int)$j['account_id']!==(int)$l['bank_account_id']||$j['je_status']!=='posted'||(int)$j['branch_id']!==(int)$l['branch_id'])throw new DomainException('Journal line not eligible for this branch/account.','bank_journal_scope_invalid',422);$journalDate=substr((string)$j['entry_date'],0,10);if($journalDate<(string)$l['statement_from']||$journalDate>(string)$l['statement_to'])throw new DomainException('Journal line is outside the reconciliation period.','bank_journal_date_outside_period',422);
   $already=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('bank_statement_lines')." WHERE matched_journal_line_id=%d AND status='matched' AND id<>%d",$journalLine,$line));if($already)throw new DomainException('Journal line is already matched to another statement line.','bank_journal_already_matched',409);$statement=round((float)$l['credit']-(float)$l['debit'],2);$journal=round((float)$j['debit']-(float)$j['credit'],2);if(abs($statement-$journal)>.005)throw new DomainException('Bank amount mismatch.');Db::mustUpdate($db,Db::table('bank_statement_lines'),['status'=>'matched','matched_journal_line_id'=>$journalLine],['id'=>$line]);Audit::add($a,'bank_line.match','bank_statement_line',$line,['branch_id'=>(int)$l['branch_id'],'reconciliation_id'=>(int)$l['reconciliation_id'],'journal_line_id'=>$journalLine]);return['id'=>$line,'status'=>'matched'];
  });
 }
 public static function bankExclude(Actor $a,int $line,string $reason):array{$reason=trim($reason);if(strlen($reason)<5)throw new DomainException('Reason required.');return Transaction::run(function()use($a,$line,$reason){$db=Db::wpdb();$l=$db->get_row($db->prepare("SELECT bl.*,r.company_id,r.branch_id,r.status recon_status FROM ".Db::table('bank_statement_lines')." bl JOIN ".Db::table('bank_reconciliations')." r ON r.id=bl.reconciliation_id WHERE bl.id=%d AND r.company_id=%d FOR UPDATE",$line,$a->companyId),ARRAY_A);if(!$l||$l['recon_status']!=='draft')throw new DomainException('Draft bank line not found.');Guard::branch($a,(int)$l['branch_id'],Capabilities::BANK_RECONCILE);$updated=$db->update(Db::table('bank_statement_lines'),['status'=>'excluded','matched_journal_line_id'=>null,'exclusion_reason'=>$reason,'excluded_by'=>$a->employeeId,'excluded_at'=>Db::now()],['id'=>$line]);if($updated===false)throw new DomainException('Bank line exclusion failed.','bank_line_store_failed',500);Audit::add($a,'bank_line.exclude','bank_statement_line',$line,['branch_id'=>(int)$l['branch_id'],'reason'=>$reason]);return['id'=>$line,'status'=>'excluded'];});}
 public static function bankFinalize(Actor $a,int $id):array{Guard::cap($a,Capabilities::BANK_RECONCILE);return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('bank_reconciliations');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='draft')throw new DomainException('Draft reconciliation not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);if((int)$r['created_by']===$a->employeeId)throw new DomainException('Reconciliation maker cannot finalize own reconciliation.','maker_checker_required',409);$lineTable=Db::table('bank_statement_lines');$lineCount=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$lineTable} WHERE reconciliation_id=%d",$id));if($lineCount<1)throw new DomainException('Import bank statement lines before finalizing.','bank_statement_required',409);if((int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$lineTable} WHERE reconciliation_id=%d AND status='unmatched'",$id)))throw new DomainException('Resolve all unmatched lines.','bank_unmatched',409);$totals=$db->get_row($db->prepare("SELECT COALESCE(SUM(credit),0) credits,COALESCE(SUM(debit),0) debits FROM {$lineTable} WHERE reconciliation_id=%d",$id),ARRAY_A);$calculated=round((float)$r['opening_balance']+(float)$totals['credits']-(float)$totals['debits'],2);if(abs($calculated-(float)$r['closing_balance'])>.005)throw new DomainException('Statement opening + credits - debits must equal closing balance.','bank_statement_balance_mismatch',409);$updated=$db->update($t,['status'=>'finalized','finalized_by'=>$a->employeeId,'finalized_at'=>Db::now()],['id'=>$id]);if($updated===false)throw new DomainException('Bank reconciliation finalize failed.','bank_reconciliation_store_failed',500);Audit::add($a,'bank_reconciliation.finalize','bank_reconciliation',$id,['branch_id'=>(int)$r['branch_id'],'account_id'=>(int)$r['bank_account_id']]);return['id'=>$id,'status'=>'finalized'];});}
}
